cat << 'EOF' > patch_wsTestSupport.ts
import fs from 'node:fs';
let content = fs.readFileSync('src/transport/wsTestSupport.ts', 'utf8');
content = content.replace('const servers: Array<{stop: () => Promise<void>}> = [];', 'const servers: Array<HalServer> = [];\n\nexport const eventually = async (check: () => boolean): Promise<void> => {\n  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));\n};');
content = content.replace(
`export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}`,
`export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

export const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: any; frames: any[]}> => {
  const client = connectClient(url, 't');
  const frames: any[] = [];
  let connected: any = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw));
      if (frame.type === 'connected') {
        connected = frame;
        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      frames.push(frame);
    });
  });
  return {connected, frames};
};`);
fs.writeFileSync('src/transport/wsTestSupport.ts', content);
EOF
node patch_wsTestSupport.ts
rm patch_wsTestSupport.ts

